  text = m.group(0)
  if text[:2] == "&#":
    try:
      if text[:3] == "&#x":
        return unichr(int(text[3:-1], 16))
      else:
        return unichr(int(text[2:-1]))
    except ValueError:
      pass
  else:
    try:
      text = unichr(_unescape[text[1:-1]])
    except KeyError:
      pass
  return text
