if match(r'^#([a-fA-F0-9]{6})$', color):
    return '#' + ''.join(color[i] for i in [1, 3, 5]).lower()
elif match(r'^#([a-fA-F0-9]{3})$', color):
    return color.lower()
else:
    raise ValueError("Invalid color format. Expected '#xxxxxx' or '#xxx'")

if match(r"#[0-9a-fA-F]{6}\Z", color):
    # If color is in the format '#xxxxxx', convert it to '#xxx'
    return "#" + color[1:2] + color[3:4] + color[5:6]
elif match(r"#[0-9a-fA-F]{3}\Z", color):
    # If color is in the format '#xxx', convert it to lowercase
    return color.lower()
else:
    raise ValueError("Invalid color format. Expected '#xxxxxx' or '#xxx'.")

