# Autocomplete helper functions
def match_stream_and_topic(text: str) -> Tuple[Optional[str], Optional[str]]:
    match = re.match(REGEX_STREAM_AND_TOPIC_FENCED, text)
    if match:
        return match.group("stream"), match.group("topic")
    match = re.match(REGEX_STREAM_AND_TOPIC_UNFENCED, text)
    if match:
        return match.group("stream"), match.group("topic")
    return None, None

def match_emoji(text: str) -> Tuple[Optional[str], Optional[str]]:
    match = re.match(REGEX_EMOJI_FENCED, text)
    if match:
        return match.group("emoji_name"), match.group("emoji_code")
    match = re.match(REGEX_EMOJI_UNFENCED, text)
    if match:
        return match.group("emoji_name"), match.group("emoji_code")
    return None, None

def match_user_group(text: str) -> Tuple[Optional[str], Optional[str]]:
    match = re.match(REGEX_USER_GROUP_FENCED, text)
    if match:
        return match.group("user_group_name"), match.group("user_group_id")
    match = re.match(REGEX_USER_GROUP_UNFENCED, text)
    if match:
        return match.group("user_group_name"), match.group("user_group_id")
    return None, None

