                metric = metrics[metric_name]
                if metric.type == 'histogram' and accumulate:
                    # Accumulate histogram buckets
                    for i, bucket in enumerate(metric.samples):
                        if bucket.name == name and bucket.labels == labels:
                            bucket.bucket = [x + y for x, y in zip(bucket.bucket, value['bucket'])]
                            bucket.sum = bucket.sum + value['sum']
                            bucket.count = bucket.count + value['count']
                            break
                    else:
                        # If no existing sample matches, create a new one
                        metric.samples.append(Sample(name, labels, value))
                else:
                    # For non-histogram metrics, just append the samples
