        # Process each source.
        for name, source in self.sources.items():
            logger.info(f"Processing source '{name}'")
            try:
                for artifact in source.artifacts():
                    # Check whitelist.
                    if self._is_whitelisted(artifact):
                        continue

                    # Send to each operator.
                    for operator_name, operator in self.operators.items():
                        try:
                            operator.handle_artifact(artifact)
                        except Exception:
                            logger.exception(f"Error in operator '{operator_name}'")

            except Exception:
                logger.exception(f"Error in source '{name}'")

        # Sleep, if configured.
        if self.config.sleep:
