while True:
    start_time = time.time()

    # Get artifacts from all sources.
    for name, source in self.sources.items():
        try:
            artifacts = source.artifacts()
            self.statsd.incr(f'source.{name}', len(artifacts))
            logger.debug(f"Found {len(artifacts)} artifacts from {name}")

            # Filter out whitelisted artifacts.
            artifacts = [a for a in artifacts if not self._is_whitelisted(a)]

            # Send artifacts to all operators.
            for operator_name, operator in self.operators.items():
                try:
                    operator.handle_artifacts(artifacts)
                    self.statsd.incr(f'operator.{operator_name}', len(artifacts))
                except Exception:
                    logger.exception(f"Error in operator '{operator_name}'")

        except Exception:
            logger.exception(f"Error in source '{name}'")

    # Update state DB.
    self.statedb.commit()

    # Sleep until next run, if configured to run as a daemon.
    if self.config.run_once():
        break
    else:
        run_time = time.time() - start_time
        sleep_time = self.config.sleep() - run_time
        if sleep_time > 0:
            time.sleep(sleep_time)

if self.config.daemon():
    while True:
        self._run_once()
        time.sleep(self.config.sleep())
else:
    self._run_once()

while True:
    start_time = time.time()
    self.statsd.incr('run')

    # Get artifacts from all sources.
    all_artifacts = collections.defaultdict(list)
    for name, source in self.sources.items():
        try:
            artifacts = source.artifacts()
            all_artifacts[name].extend(artifacts)
            self.statsd.incr(f'sources.{name}', len(artifacts))
        except Exception:
            logger.exception(f"Error reading from source '{name}'")

    # Filter out whitelisted artifacts.
    for name, artifacts in all_artifacts.items():
        all_artifacts[name] = [
            artifact for artifact in artifacts
            if not self._is_whitelisted(artifact)
        ]

    # Send artifacts to all operators.
    for name, operator in self.operators.items():
        for source_name, artifacts in all_artifacts.items():
            try:
                operator.handle_artifacts(artifacts, source_name)
                self.statsd.incr(f'operators.{name}', len(artifacts))
            except Exception:
                logger.exception(f"Error in operator '{name}'")

    # Commit state.
    self.statedb.commit()

    # If not running as a daemon, break after the first run.
