def toc_hook(state, startLine, endLine, silent):
    """
    Hook function that will be called for each markdown block.
    """
    if not silent:
        token = state.tokens[startLine]
        if token.type == 'heading_open':
            level = int(token.tag[1:])
            if min_level <= level <= max_level:
                content_token = state.tokens[startLine + 1]
                title = striptags(content_token.content)
                id = heading_id(title) if heading_id else title
                state.env.setdefault('toc', []).append({
                    'level': level,
                    'title': title,
                    'id': id
                })
    return False

md.block.ruler.before('paragraph', 'toc', toc_hook, {'alt': []})

