def save_toc_item(state, token):
    level = int(token.tag.lstrip('h'))
    if min_level <= level <= max_level:
        id = heading_id(token.content) if heading_id else token.map[0]
        title = striptags(token.content)
        md.toc.append((level, id, title))

md.add_render_rule('heading_open', save_toc_item)

def hook(state, token):
    if token.tag not in ('h1', 'h2', 'h3', 'h4', 'h5', 'h6'):
        return

    level = int(token.tag[1])
    if level < min_level or level > max_level:
        return

    toc_item = {
        'level': level,
        'content': striptags(token.children[0].content),
    }

    if heading_id:
        toc_item['id'] = heading_id(toc_item['content'])

    state.env.setdefault('toc', []).append(toc_item)

md.add_render_rule('heading_open', hook)

def toc_hook(state, startLine, endLine, silent):
    if not silent:
        token = state.tokens[startLine]
        if token.type == 'heading_open':
            level = int(token.tag[1:])
            if min_level <= level <= max_level:
                content = striptags(state.tokens[startLine + 1].content)
                if heading_id:
                    id = heading_id(content)
                else:
                    id = content.replace(' ', '-')
                state.env['toc'].append({
                    'level': level,
                    'content': content,
                    'id': id
                })
    return False

md.inline.ruler.before('emphasis', 'toc', toc_hook)

def toc_hook(state, startLine, endLine, silent):
