        'level': level,
        'title': title,
        'id': id
    })
    return False

md.inline.ruler.before('emphasis', 'toc', toc_hook)

def toc_hook(state, startLine, endLine, silent):
    # Get the token list
    tokens = state.tokens

    # Initialize the TOC list
    state.env['toc'] = []

    # Iterate over the tokens
    for token in tokens:
        if token['type'] == 'heading_open':
            # Check if the heading level is within the specified range
            if min_level <= int(token['tag'][1]) <= max_level:
                # Get the heading text by stripping the tags
                heading_text = striptags(tokens[tokens.index(token) + 1]['content'])

                # Generate the heading ID
                if heading_id:
                    id = heading_id(heading_text)
                else:
                    id = heading_text.replace(' ', '-').lower()

                # Add the heading to the TOC
                state.env['toc'].append({
                    'level': int(token['tag'][1]),
                    'text': heading_text,
                    'id': id
                })

    return False

# Add the hook to the markdown instance
md.inline.ruler.after('emphasis', 'toc', toc_hook)

if not hasattr(md, 'toc_tokens'):
