def toc_hook(state, startLine, endLine, silent):
    token = state.tokens[startLine]
    if token.type == 'heading_open':
        level = int(token.tag[1:])
        if min_level <= level <= max_level:
            content_token = state.tokens[startLine + 1]
            text = striptags(content_token.content)
            if heading_id:
                id = heading_id(text)
            else:
                id = text.lower().replace(' ', '-')
            md.toc_tokens.append((level, text, id))
    return False

md.block.ruler.before('heading', 'toc', toc_hook, {'alt': []})

def add_toc_item(state, start_line, end_line, silent):
    token = state.tokens[start_line]
    if token.type == "heading_open":
        level = int(token.tag[1])
        if min_level <= level <= max_level:
            content_token = state.tokens[start_line + 1]
            title = striptags(content_token.content)
            if heading_id is None:
                id = title.lower().replace(" ", "-")
            else:
                id = heading_id(title)
            state.env["toc"].append({"level": level, "title": title, "id": id})
    return False

md.block.register_rule("toc_item", add_toc_item, {"alt": ("paragraph", "reference", "blockquote")}, 0)
