s = s.replace("%", "~25")
parts = s.split("~")
decoded_parts = [parts[0]]
for part in parts[1:]:
    if len(part) < 2:
        decoded_parts.append("~")
        decoded_parts.append(part)
    else:
        try:
            decoded_parts.append(chr(int(part[:2], 16)))
            decoded_parts.append(part[2:])
        except ValueError:
            decoded_parts.append("~")
            decoded_parts.append(part)
return "".join(decoded_parts).replace("~25", "%")

