class ReadTransaction:
    def __init__(self, lock):
        self.lock = lock

    def __enter__(self):
        self.lock.acquire_read()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.lock.release_read()

return ReadTransaction(self._lock)

