@wraps(f)
def wrapper(*args, **kwargs):
    global _in_retry, _retry_count
    if _in_retry:
        return f(*args, **kwargs)
    _in_retry = True
    _retry_count = 0
    while True:
        try:
            result = f(*args, **kwargs)
        except (AutoReconnect, OperationFailure, DuplicateKeyError, ServerSelectionTimeoutError, BulkWriteError) as e:
            _retry_count += 1
            if _retry_count > _MAX_RETRIES:
                _log_exception(logger, 'mongo_retry: exceeded max retries', f, *args, **kwargs)
                raise
            sleep(min(2 ** _retry_count, 120))
            continue
        except Exception:
            _log_exception(logger, 'mongo_retry: unhandled exception', f, *args, **kwargs)
            raise
        else:
            _in_retry = False
            return result
return wrapper

