if input_source.startswith("https://tenor.com/view/"):
    gif_id = input_source.split('/')[-1]
    url = f"https://api.tenor.com/v1/gifs/{gif_id}?key={api_key}"
    response = requests.get(url)
    if response.status_code == 200:
        gif_url = response.json()["results"][0]["media"][0]["gif"]["url"]
        return gif_url
    else:
        raise Exception("Failed to get GIF URL from Tenor API")
else:
    url = f"https://api.tenor.com/v1/search?q={input_source}&key={api_key}&limit=1"
    response = requests.get(url)
    if response.status_code == 200:
        gif_url = response.json()["results"][0]["media"][0]["gif"]["url"]
        return gif_url
