try:
    devices = self._gc_ipu_info.getDevices()
    for device in devices:
        metrics = self._gc_ipu_info.getMetrics(device)
        if metrics["pid"] != self._pid:
            continue

        device_name = self.name.format(device["board"], device["ipu"])
        if device_name not in self._devices_called:
            self._devices_called.add(device_name)
            for key, value in metrics.items():
                parsed_metric = self.parse_metric(key, value)
                if parsed_metric is not None:
                    wandb.log({f"{device_name}.{parsed_metric[0]}": parsed_metric[1]})
        else:
            for key in self.variable_metric_keys:
                value = metrics.get(key)
                if value is not None:
                    parsed_metric = self.parse_metric(key, value)
                    if parsed_metric is not None:
                        wandb.log({f"{device_name}.{parsed_metric[0]}": parsed_metric[1]})

except Exception as e:
    print(f"Error occurred while sampling IPU stats: {str(e)}")

try:
    devices = self._gc_ipu_info.getDevices()
    for device in devices:
        metrics = device.getMetrics()
        for key, value in metrics.items():
            if key == "pid" and value != self._pid:
                continue

            parsed = self.parse_metric(key, value)
            if parsed is None:
                continue

            key, value = parsed
            if key not in self._devices_called or key in self.variable_metric_keys:
                self._devices_called.add(key)
                self.samples.append({key: value})

except Exception as e:
    raise RuntimeError(f"Error sampling IPU stats: {e}")

try:
