    if metrics["process id"] != self._pid:
        continue

    device_name = device.getName()
    if device_name not in self._devices_called or any(
        key in self.variable_metric_keys for key in metrics.keys()
    ):
        self._devices_called.add(device_name)
        for key, value in metrics.items():
            parsed_metric = self.parse_metric(key, value)
            if parsed_metric is not None:
                wandb.log({self.name.format(device_name, parsed_metric[0]): parsed_metric[1]})

